// Starts the production build (`build/handler.js`) on PORT and HOST.
//
// adapter-node in SvelteKit 3 only learns the site's origin at build time
// (`paths.origin`), and otherwise assumes `https`. This server is reached over
// plain http, with its public URL given at runtime in ORIGIN, so it tells the
// handler which protocol and host each request was made to.
import http from 'node:http';
import process from 'node:process';

const PROTO = 'x-bookshelf-proto';
const HOST = 'x-bookshelf-host';

process.env.PROTOCOL_HEADER = PROTO;
process.env.HOST_HEADER = HOST;
delete process.env.PORT_HEADER;

const { handler } = await import('./build/handler.js');

const origin = process.env.ORIGIN ? new URL(process.env.ORIGIN) : null;
const port = Number(process.env.PORT || 3000);
const host = process.env.HOST || '0.0.0.0';

const server = http.createServer((req, res) => {
	const request_host = req.headers.host;
	const same_host = !!request_host && req.headers.origin === `http://${request_host}`;

	// A request carrying its own host as Origin is same-origin; anything else
	// is checked against the configured ORIGIN.
	const self = origin && !same_host ? origin : null;
	req.headers[PROTO] = self ? self.protocol.slice(0, -1) : 'http';
	req.headers[HOST] = self ? self.host : request_host;

	// Non-browser clients send no Origin header; treat them as same-origin.
	if (req.method === 'POST' && !req.headers.origin && request_host) {
		req.headers.origin = self ? self.origin : `http://${request_host}`;
	}

	handler(req, res);
});

server.listen(port, host, () => {
	console.log(`Listening on http://${host}:${port}`);
});

function shutdown() {
	server.close(() => process.exit(0));
	server.closeIdleConnections();
	setTimeout(() => {
		server.closeAllConnections();
		process.exit(0);
	}, 5000).unref();
}

process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
EOF
